import perceivo


@perceivo.policy
async def iterator_policy_internal(
    input: perceivo.primitives.PolicyInput,
) -> perceivo.primitives.PolicyOutput:
    """Decide whether a failed item ends the Iterator's loop."""
    rd = input.request_data or {}
    failed = int(rd.get("failed", 0) or 0)
    max_failures = int(rd.get("max_failures", 0) or 0)

    if not rd.get("continue_on_error", False):
        reason = f"item failed and Continue On Error is off: {rd.get('last_error', '')}".rstrip(
            ": "
        )
    elif max_failures and failed >= max_failures:
        reason = f"{failed} items failed, reaching Max Failures ({max_failures})"
    else:
        return perceivo.primitives.PolicyOutput(
            next_state="continue", response_data={"should_exit": False, "exit_reason": ""}
        )
    return perceivo.primitives.PolicyOutput(
        next_state="exit", response_data={"should_exit": True, "exit_reason": reason}
    )

