import asyncio

import perceivo

_FALSY = ("false", "0", "no", "off", "")


def _flag(value) -> bool:
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    return str(value).strip().lower() not in _FALSY


def _whole(name: str, default: int, low: int, high: int) -> int:
    raw = perceivo.params.get(name, default)
    if raw is None or raw == "":
        raw = default
    try:
        number = float(raw)
    except (TypeError, ValueError):
        raise ValueError(f"{name} must be a whole number; got {raw!r}.") from None
    if number != int(number) or not low <= number <= high:
        raise ValueError(f"{name} must be a whole number from {low} to {high}; got {raw!r}.")
    return int(number)


def _resolve(data: dict, path: str):
    value = data
    for part in path.split("."):
        if not isinstance(value, dict) or part not in value:
            return None
        value = value[part]
    return value


async def _should_stop(
    index: int, completed: int, failed: int, total: int, last_error: str, settings: dict
) -> tuple[bool, str]:
    """Ask the paired policy whether a failure ends the loop. No answer fails the run."""
    try:
        verdict = await perceivo.flow.invoke(
            port_name="policy",
            request_data={
                "completed": completed,
                "failed": failed,
                "total": total,
                "last_error": last_error,
                **settings,
            },
        )
    except Exception as exc:
        raise RuntimeError(
            f"Iterator stopped at item {index} of {total}: "
            f"the policy could not be reached ({type(exc).__name__})"
        ) from exc
    answer = (verdict or {}).get("response_data") or {}
    return bool(answer.get("should_exit", True)), str(answer.get("exit_reason") or "")


@perceivo.fsm
async def iterator(input: perceivo.primitives.FsmInput) -> perceivo.primitives.FsmOutput:
    """Run the handler slot once per item of an array, in order or a few at a time.

    The array is read from the incoming data at Item Key. Each run receives the
    incoming data plus iterator_item, iterator_index and iterator_total.
    After a failed item the paired policy decides whether to carry on; when it
    stops the loop, the run fails with that item's error. Failures are tolerated
    only when Continue On Error is on, and are then listed in errors.
    """
    item_key = str(perceivo.params.get("item_key", "items") or "items").strip()
    max_parallel = _whole("max_parallel", 1, 1, 50)
    max_failures = _whole("max_failures", 0, 0, 1_000_000)
    continue_on_error = _flag(perceivo.params.get("continue_on_error", False))

    data = dict(input.request_data or {})
    if input.artifact is not None and isinstance(input.artifact.data, dict):
        data = {**input.artifact.data, **data}

    items = _resolve(data, item_key)
    if items is None:
        raise ValueError(f"No '{item_key}' in the incoming data; received {sorted(data)}.")
    if not isinstance(items, list):
        raise ValueError(f"'{item_key}' must be an array; got {type(items).__name__}.")

    total = len(items)
    settings = {"continue_on_error": continue_on_error, "max_failures": max_failures}
    results: list = [None] * total
    errors: list = []
    state = {"completed": 0, "failed": 0, "stopped": False}
    perceivo.log.info("Iterator starting", total=total, max_parallel=max_parallel)

    async def run_item(index: int) -> None:
        if state["stopped"]:
            return
        request = {
            **data,
            "iterator_item": items[index],
            "iterator_index": index,
            "iterator_total": total,
        }
        try:
            outcome = await perceivo.flow.invoke(port_name="handler", request_data=request)
        except Exception as exc:
            state["failed"] += 1
            message = f"{type(exc).__name__}: {exc}"
            errors.append({"index": index, "error": message})
            perceivo.log.warning("Iterator item failed", index=index, error_type=type(exc).__name__)
            if state["stopped"]:
                return
            try:
                stop, reason = await _should_stop(
                    index, state["completed"], state["failed"], total, message, settings
                )
            except RuntimeError:
                state["stopped"] = True
                raise
            if not stop or state["stopped"]:
                return
            state["stopped"] = True
            raise RuntimeError(
                f"Iterator stopped at item {index} of {total}: "
                f"{reason or 'the policy ended the loop'}"
            ) from exc
        results[index] = (outcome or {}).get("response_data") or {}
        state["completed"] += 1

    if max_parallel == 1:
        for index in range(total):
            await run_item(index)
    else:
        gate = asyncio.Semaphore(max_parallel)

        async def bounded(index: int) -> None:
            async with gate:
                await run_item(index)

        # Every started item is awaited before the stop is raised, so none is left
        # running behind a failed run; items not yet started see the stop and skip.
        outcomes = await asyncio.gather(*(bounded(i) for i in range(total)), return_exceptions=True)
        for outcome in outcomes:
            if isinstance(outcome, BaseException):
                raise outcome

    errors.sort(key=lambda e: e["index"])
    summary = {
        "results": results,
        "total": total,
        "completed": state["completed"],
        "failed": state["failed"],
        "errors": errors,
    }
    perceivo.log.info("Iterator finished", completed=state["completed"], failed=state["failed"])
    return perceivo.primitives.FsmOutput(
        artifact=perceivo.primitives.Artifact(
            type=perceivo.primitives.ArtifactType.JSON, data=summary, mime_type="application/json"
        ),
        response_data=summary,
    )

